import asyncio

async def rd(path):
    return await yuki_workspace_read({"path": path})

async def wr(path, text, expected=None):
    p = {"path": path, "text": text}
    if expected:
        p["expected_version"] = expected
    return await yuki_workspace_write(p)

def parse(text):
    d = {}
    for line in text.splitlines():
        line = line.strip()
        if not line or "=" not in line:
            continue
        k, v = line.split("=", 1)
        d[k.strip()] = v.strip()
    return d

report = {"logs": [], "audit": [], "errors": []}
visited = []

cur = "nodes/34aaa432.txt"
for i in range(2000):
    r = await rd(cur)
    if not r.get("ok"):
        report["errors"].append(("read_fail", cur, r.get("error"), r.get("status")))
        break
    data = r.get("data") or {}
    text = data.get("text", "")
    node = parse(text)
    val = node.get("value")
    left = node.get("left")
    right = node.get("right")
    if val is None:
        report["errors"].append(("no_value", cur, text))
        break
    visited.append((cur, val))
    report["logs"].append({"i": i, "path": cur, "value": val, "left": left, "right": right})

    # audit file right after reading this node, before next read / chain write
    apath = "audit/%02d.txt" % i
    acontent = val + "\n"
    pre = await rd(apath)
    if pre.get("ok"):
        pd = pre.get("data") or {}
        if pd.get("text") == acontent:
            report["audit"].append({"i": i, "file": apath, "action": "already_ok"})
        else:
            report["audit"].append({"i": i, "file": apath, "action": "exists_mismatch", "text": pd.get("text")})
    else:
        w = await wr(apath, acontent)
        report["audit"].append({"i": i, "file": apath, "action": "wrote", "ok": w.get("ok"), "status": w.get("status"), "error": w.get("error")})

    nxt = left if (int(val) % 2 == 0) else right
    if nxt is None or nxt == "" or nxt.upper() == "END":
        report["end_next"] = nxt
        break
    cur = nxt

total = sum(int(v) for _, v in visited)
lines = ["%s\t%s" % (p, v) for p, v in visited] + ["TOTAL\t%d" % total]
chain_text = "\n".join(lines) + "\n"

r = await rd("chain.tsv")
if r.get("ok"):
    d = r.get("data") or {}
    if d.get("text") == chain_text:
        report["chain"] = {"action": "already_ok"}
    else:
        w = await wr("chain.tsv", chain_text, d.get("version"))
        report["chain"] = {"action": "overwrote", "ok": w.get("ok"), "status": w.get("status"), "error": w.get("error")}
else:
    w = await wr("chain.tsv", chain_text)
    report["chain"] = {"action": "wrote", "ok": w.get("ok"), "status": w.get("status"), "error": w.get("error")}

# readback verification
v = await rd("chain.tsv")
vd = v.get("data") or {}
report["readback"] = {
    "ok": v.get("ok"),
    "status": v.get("status"),
    "version": vd.get("version"),
    "text": vd.get("text"),
    "matches_expected": vd.get("text") == chain_text,
    "expected": chain_text,
}
report["n_nodes"] = len(visited)
report["total"] = total
report

