GRAPH = {"/workspace/nodes/291e5bdc.txt": "value=24\nleft=nodes/de492501.txt\nright=nodes/decoy-10.txt\n", "/workspace/nodes/3b8ab481.txt": "value=94\nleft=nodes/291e5bdc.txt\nright=nodes/decoy-9.txt\n", "/workspace/nodes/3dfceada.txt": "value=89\nleft=nodes/decoy-1.txt\nright=nodes/f93f4f57.txt\n", "/workspace/nodes/53324b3e.txt": "value=38\nleft=nodes/d56677b0.txt\nright=nodes/decoy-6.txt\n", "/workspace/nodes/60a6bb1c.txt": "value=54\nleft=nodes/3dfceada.txt\nright=nodes/decoy-0.txt\n", "/workspace/nodes/7df56c45.txt": "value=41\nleft=nodes/decoy-5.txt\nright=nodes/53324b3e.txt\n", "/workspace/nodes/af91b4b8.txt": "value=14\nleft=nodes/7df56c45.txt\nright=nodes/decoy-4.txt\n", "/workspace/nodes/afda9bb5.txt": "value=33\nleft=nodes/decoy-8.txt\nright=nodes/3b8ab481.txt\n", "/workspace/nodes/bda6f8d4.txt": "value=91\nleft=nodes/decoy-3.txt\nright=nodes/af91b4b8.txt\n", "/workspace/nodes/d56677b0.txt": "value=60\nleft=nodes/afda9bb5.txt\nright=nodes/decoy-7.txt\n", "/workspace/nodes/de492501.txt": "value=61\nleft=nodes/decoy-11.txt\nright=END\n", "/workspace/nodes/f93f4f57.txt": "value=82\nleft=nodes/bda6f8d4.txt\nright=nodes/decoy-2.txt\n"}

def parse_kv(text):
    d = {}
    for line in text.splitlines():
        s = line.strip()
        if not s:
            continue
        if "=" in s:
            k, v = s.split("=", 1)
            d[k.strip()] = v.strip()
    return d

def norm(p):
    p = str(p).strip()
    return p if p.startswith("/") else "/workspace/" + p

async def main():
    g = {k: parse_kv(v) for k, v in GRAPH.items()}
    cur = "nodes/60a6bb1c.txt"
    visited = []
    guard = 0
    while True:
        nd = g[norm(cur)]
        val = int(nd["value"])
        visited.append((cur, val))
        nxt = nd["left"] if val % 2 == 0 else nd["right"]
        if str(nxt).strip().upper() == "END":
            break
        cur = nxt
        guard += 1
        if guard > 200:
            return {"error": "loop guard"}
    total = sum(v for _, v in visited)

    lr = await yuki_workspace_list({"path": "/workspace/audit", "limit": 100})
    existing = set()
    if lr.get("ok"):
        existing = set(it["path"] for it in lr["data"]["items"])

    writes = []
    for i, (p, v) in enumerate(visited):
        ap = "/workspace/audit/%02d.txt" % i
        if ap in existing:
            writes.append({"path": ap, "skipped": True})
            continue
        wr = await yuki_workspace_write({"path": ap, "text": str(v) + "\n"})
        writes.append({"path": ap, "ok": wr.get("ok"), "err": wr.get("error"), "ver": wr.get("data")})
        if not wr.get("ok"):
            return {"stage": "audit_write_fail", "writes": writes}

    ctext = "".join("%s\t%d\n" % (p, v) for p, v in visited) + "TOTAL\t%d\n" % total
    cr = await yuki_workspace_read({"path": "/workspace/chain.tsv"})
    if cr.get("ok"):
        if cr["data"]["text"] == ctext:
            cw = {"skipped_exact_match": True}
        else:
            w = await yuki_workspace_write({"path": "/workspace/chain.tsv", "text": ctext, "expected_version": cr["data"]["version"]})
            cw = {"ok": w.get("ok"), "err": w.get("error")}
    else:
        w = await yuki_workspace_write({"path": "/workspace/chain.tsv", "text": ctext})
        cw = {"ok": w.get("ok"), "err": w.get("error")}

    rb = await yuki_workspace_read({"path": "/workspace/chain.tsv"})
    rbtext = rb["data"].get("text") if rb.get("ok") else None
    return {"visited": visited, "total": total, "audit_writes": writes, "chain_write": cw,
            "readback_ok": rb.get("ok"), "readback_text": rbtext,
            "verified": bool(rb.get("ok")) and rbtext == ctext, "expected_chain": ctext}

await main()
